import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    idx = 0

    UP, DOWN, LEFT, RIGHT = 0, 1, 2, 3
    UPLEFT, UPRIGHT, DOWNLEFT, DOWNRIGHT = 4, 5, 6, 7

    dx = [0, 0, -1, 1, -1, 1, -1, 1]
    dy = [1, -1, 0, 0, 1, 1, -1, -1]

    MAX = 5 * 30 + 5

    def rot(d):
        if d == UP:
            return (UPLEFT, UPRIGHT)
        if d == DOWN:
            return (DOWNLEFT, DOWNRIGHT)
        if d == LEFT:
            return (UPLEFT, DOWNLEFT)
        if d == RIGHT:
            return (UPRIGHT, DOWNRIGHT)
        if d == UPLEFT:
            return (UP, LEFT)
        if d == UPRIGHT:
            return (UP, RIGHT)
        if d == DOWNLEFT:
            return (DOWN, LEFT)
        if d == DOWNRIGHT:
            return (DOWN, RIGHT)

    marked = set()
    mp = set()
    t = [0] * 100

    n = int(data[idx]); idx += 1
    for i in range(1, n + 1):
        t[i] = int(data[idx]); idx += 1

    ans = 0
    Q = deque()
    Q.append((MAX, MAX, UP, 1, 1))

    marked.add((MAX, MAX, UP, 1, 1))
    mp.add((MAX, MAX))
    ans += 1

    while Q:
        vx, vy, vdir, lev, far = Q.popleft()

        if (vx, vy) not in mp:
            mp.add((vx, vy))
            ans += 1

        x2, y2 = vx, vy

        if lev == n + 1:
            continue

        if far != t[lev]:
            x2 += dx[vdir]
            y2 += dy[vdir]
            if (x2, y2, vdir, lev, far + 1) in marked:
                continue
            marked.add((x2, y2, vdir, lev, far + 1))
            Q.append((x2, y2, vdir, lev, far + 1))
        else:
            d1, d2 = rot(vdir)
            if (vx, vy, d1, lev + 1, 0) not in marked:
                marked.add((vx, vy, d1, lev + 1, 0))
                Q.append((vx, vy, d1, lev + 1, 0))
            if (vx, vy, d2, lev + 1, 0) not in marked:
                marked.add((vx, vy, d2, lev + 1, 0))
                Q.append((vx, vy, d2, lev + 1, 0))

    print(ans)

main()
